namespace sv_94b69415f7564cdb97423179eae31bb6.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped (circuit-scoped) service that holds theme state for a single user session.
/// All interactive components on the same circuit share this instance.
/// </summary>
public class ThemeService
{
    private ThemeMode _currentTheme = ThemeMode.System;
    private string _accentColor = "#0d6efd";

    public ThemeMode CurrentTheme
    {
        get => _currentTheme;
        set
        {
            if (_currentTheme == value) return;
            _currentTheme = value;
            NotifyStateChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyStateChanged();
        }
    }

    /// <summary>
    /// Event raised whenever theme or accent color changes.
    /// Components subscribe to this to re-render on changes.
    /// </summary>
    public event Action? OnChange;

    private void NotifyStateChanged() => OnChange?.Invoke();
}

@* Interactive island — lives in the static layout but runs on the circuit *@
@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<span class="theme-indicator badge"
      style="background-color: @ThemeService.AccentColor; color: white;">
    @ThemeService.CurrentTheme.ToString()
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += StateHasChanged;
    }

    public void Dispose()
    {
        ThemeService.OnChange -= StateHasChanged;
    }
}

@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<div class="theme-toggle">
    <button class="btn btn-sm @ButtonClass" @onclick="CycleTheme">
        @Icon @ThemeService.CurrentTheme
    </button>
</div>

@code {
    private string Icon => ThemeService.CurrentTheme switch
    {
        ThemeMode.Light => "☀️",
        ThemeMode.Dark => "🌙",
        _ => "💻"
    };

    private string ButtonClass => ThemeService.CurrentTheme switch
    {
        ThemeMode.Light => "btn-outline-warning",
        ThemeMode.Dark => "btn-outline-dark",
        _ => "btn-outline-secondary"
    };

    private void CycleTheme()
    {
        ThemeService.CurrentTheme = ThemeService.CurrentTheme switch
        {
            ThemeMode.Light => ThemeMode.Dark,
            ThemeMode.Dark => ThemeMode.System,
            _ => ThemeMode.Light
        };
    }

    protected override void OnInitialized()
    {
        ThemeService.OnChange += StateHasChanged;
    }

    public void Dispose()
    {
        ThemeService.OnChange -= StateHasChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<PageTitle>User Preferences</PageTitle>

<h3>User Preferences</h3>

<div class="card mt-3" style="max-width: 500px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="mb-3">
            <label class="form-label">Mode</label>
            <select class="form-select" @bind="SelectedTheme">
                @foreach (var mode in Enum.GetValues<ThemeMode>())
                {
                    <option value="@mode">@mode</option>
                }
            </select>
        </div>

        <div class="mb-3">
            <label class="form-label">Accent Color</label>
            <input type="color" class="form-control form-control-color"
                   @bind="SelectedColor" @bind:event="oninput" />
        </div>

        <div class="mb-3">
            <strong>Current:</strong>
            <span class="badge" style="background-color: @ThemeService.AccentColor; color: white;">
                @ThemeService.CurrentTheme — @ThemeService.AccentColor
            </span>
        </div>
    </div>
</div>

@code {
    private ThemeMode SelectedTheme
    {
        get => ThemeService.CurrentTheme;
        set => ThemeService.CurrentTheme = value;
    }

    private string SelectedColor
    {
        get => ThemeService.AccentColor;
        set => ThemeService.AccentColor = value;
    }

    protected override void OnInitialized()
    {
        ThemeService.OnChange += StateHasChanged;
    }

    public void Dispose()
    {
        ThemeService.OnChange -= StateHasChanged;
    }
}

